from pre_route_endpoints import sha
out=Path('experiments/frisc_critical_retention_audit_v2_2026-10-05');segfile=Path('experiments/frisc_native_sta_pair_v2_2026-10-05/segment_changes.json');diagfile=segfile.with_name('diagnostic.json');netfile=Path('experiments/frisc_native_response_diagnostic_v2_2026-10-05/net_deltas.json');basefile=Path('experiments/frisc_timing_backgrounds_v2_2026-10-05/baseline_prediction.json');candidatefile=basefile.with_name('candidate_7_prediction.json')
if out.exists():raise ValueError('fresh output required')
inputs={str(f):sha(f) for f in (segfile,diagfile,netfile,basefile,candidatefile)};segments=json.loads(segfile.read_text());assert segments['diagnostic_sha256']==sha(diagfile);nets={r['net_id']:r for r in json.loads(netfile.read_text())};base={r['connection_id']:r for r in json.loads(basefile.read_text())['connections']};candidate={r['connection_id']:r for r in json.loads(candidatefile.read_text())['connections']};rows=[]
